import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.BHpftTUY.js";const u=JSON.parse('{"title":"SCRAM family (SHA-256 and SHA-1, each with optional PLUS)","description":"yarilo-auth supports the Salted Challenge Response Authentication Mechanism family (RFC 5802 / RFC 7677) as a SASL mechanism in IMAP, POP3 and Submission.…","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/auth/scram.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/2.4.5/auth/scram.html"}],["meta",{"property":"og:title","content":"SCRAM family (SHA-256 and SHA-1, each with optional PLUS)"}],["meta",{"name":"twitter:title","content":"SCRAM family (SHA-256 and SHA-1, each with optional PLUS)"}],["meta",{"property":"og:description","content":"yarilo-auth supports the Salted Challenge Response Authentication Mechanism family (RFC 5802 / RFC 7677) as a SASL mechanism in IMAP, POP3 and Submission.…"}],["meta",{"name":"twitter:description","content":"yarilo-auth supports the Salted Challenge Response Authentication Mechanism family (RFC 5802 / RFC 7677) as a SASL mechanism in IMAP, POP3 and Submission.…"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/2.4.5/auth/scram.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/2.4.5/auth/scram.html\\",\\"headline\\":\\"SCRAM family (SHA-256 and SHA-1, each with optional PLUS)\\",\\"description\\":\\"yarilo-auth supports the Salted Challenge Response Authentication Mechanism family (RFC 5802 / RFC 7677) as a SASL mechanism in IMAP, POP3 and Submission.…\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/2.4.5/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"SCRAM family (SHA-256 and SHA-1, each with optional PLUS)\\",\\"item\\":\\"https://doc.yarilomail.org/2.4.5/auth/scram.html\\"}]}]}"]]},"headers":[],"relativePath":"auth/scram.md","filePath":"auth/scram.md","lastUpdated":1793450621000}'),n={name:"auth/scram.md"};function o(r,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="scram-family-sha-256-and-sha-1-each-with-optional-plus" tabindex="-1">SCRAM family (SHA-256 and SHA-1, each with optional PLUS) <a class="header-anchor" href="#scram-family-sha-256-and-sha-1-each-with-optional-plus" aria-label="Permalink to &quot;SCRAM family (SHA-256 and SHA-1, each with optional PLUS)&quot;">​</a></h1><p><code>yarilo-auth</code> supports the Salted Challenge Response Authentication Mechanism family (RFC 5802 / RFC 7677) as a SASL mechanism in IMAP, POP3 and Submission. SCRAM is the recommended replacement for plain-text + TLS auth: the server never sees the user&#39;s password, and the client proves possession through a salted HMAC ladder that resists offline brute-force on the wire.</p><p>The PLUS variant adds <strong>channel binding</strong> (RFC 9266 <code>tls-exporter</code>) so a successful auth additionally proves the client is on the same TLS session - defeating MITM proxies that terminate TLS at the attacker.</p><h2 id="supported-mechanisms" tabindex="-1">Supported mechanisms <a class="header-anchor" href="#supported-mechanisms" aria-label="Permalink to &quot;Supported mechanisms&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Mechanism</th><th style="text-align:left;">RFC</th><th style="text-align:left;">Use</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SCRAM-SHA-256</code></td><td style="text-align:left;">RFC 7677</td><td style="text-align:left;"><strong>Default for new deployments.</strong> PBKDF2-HMAC-SHA-256 ladder.</td></tr><tr><td style="text-align:left;"><code>SCRAM-SHA-256-PLUS</code></td><td style="text-align:left;">RFC 7677 + RFC 9266</td><td style="text-align:left;">SHA-256 + channel binding via TLS exporter.</td></tr><tr><td style="text-align:left;"><code>SCRAM-SHA-1</code></td><td style="text-align:left;">RFC 5802</td><td style="text-align:left;">Compatibility with legacy clients (older Thunderbird builds, Apple Mail fallback). PBKDF2-HMAC-SHA-1 ladder.</td></tr><tr><td style="text-align:left;"><code>SCRAM-SHA-1-PLUS</code></td><td style="text-align:left;">RFC 5802 + RFC 9266</td><td style="text-align:left;">SHA-1 + channel binding.</td></tr></tbody></table><p>SHA-1 is <strong>not deprecated for SCRAM</strong> - the HMAC construction is not broken by SHA-1 collision attacks the way digital signatures are. It is provided strictly for client compatibility; new deployments should provision SHA-256 verifiers. The two digest families are independent - a single user may carry one or the other (but only one verifier blob per user; clients negotiate the strongest mech the server advertises).</p><h2 id="when-to-enable" tabindex="-1">When to enable <a class="header-anchor" href="#when-to-enable" aria-label="Permalink to &quot;When to enable&quot;">​</a></h2><p>Enable SCRAM when:</p><ul><li>Modern MUAs are on the deployment path (Thunderbird, K-9 Mail, any client that supports SCRAM out of the box).</li><li>The threat model includes attackers with intermittent network access (SCRAM denies them the password; plain-text-over-TLS hands them the password the moment they get a single MITM window).</li><li>Compliance pressure to never store plain passwords on the server (SCRAM verifiers are derived material - operators cannot recover the original password).</li></ul><p>Skip when every client is restricted to PLAIN/LOGIN, or when the operator cannot run the one-time verifier-generation step per user.</p><h2 id="storage-format" tabindex="-1">Storage format <a class="header-anchor" href="#storage-format" aria-label="Permalink to &quot;Storage format&quot;">​</a></h2><p>Each SCRAM-enabled user&#39;s <code>password</code> column carries a reference- compatible blob - the inner shape is identical across the SHA-256 and SHA-1 families; only the scheme prefix differs:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{SCRAM-SHA-256}&lt;iterations&gt;,&lt;base64-salt&gt;,&lt;base64-stored-key&gt;,&lt;base64-server-key&gt;</span></span>
<span class="line"><span>{SCRAM-SHA-1}&lt;iterations&gt;,&lt;base64-salt&gt;,&lt;base64-stored-key&gt;,&lt;base64-server-key&gt;</span></span></code></pre></div><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{SCRAM-SHA-256}600000,gJ4oG0RpUmMrzFQ9PAGUng==,...,...</span></span>
<span class="line"><span>{SCRAM-SHA-1}600000,gJ4oG0RpUmMrzFQ9PAGUng==,...,...</span></span></code></pre></div><p>The fields:</p><ul><li><code>iterations</code> - PBKDF2-HMAC-SHA-256 iteration count.</li><li><code>salt</code> - per-user random salt (16 bytes recommended).</li><li><code>stored_<wbr>key</code> = <code>SHA-256(HMAC(salted_<wbr>password, &quot;Client Key&quot;))</code>.</li><li><code>server_<wbr>key</code> = <code>HMAC(salted_<wbr>password, &quot;Server Key&quot;)</code>.</li></ul><p><code>salted_<wbr>password = PBKDF2(password, salt, iterations)</code> - that intermediate is NEVER stored. The plain password is never stored in any form.</p><h3 id="same-blob-serves-plain-and-scram" tabindex="-1">Same blob serves PLAIN and SCRAM <a class="header-anchor" href="#same-blob-serves-plain-and-scram" aria-label="Permalink to &quot;Same blob serves PLAIN and SCRAM&quot;">​</a></h3><p>Both auth flows interpret the same column:</p><ul><li><strong>PLAIN/LOGIN</strong>: server re-derives <code>stored_<wbr>key</code> from the incoming plain password using the column&#39;s iter+salt, then constant-time compares against the stored <code>stored_<wbr>key</code>. The plain password never leaves the connection&#39;s goroutine.</li><li><strong>SCRAM-SHA-256 / -PLUS</strong>: server uses <code>stored_<wbr>key</code> + <code>server_<wbr>key</code> directly to drive challenge-response. Plain password is never involved.</li></ul><p>Operators register a user once and the same row is consumable by both flows. Mixed-MUA deployments do not need separate password columns per protocol.</p><h2 id="generating-a-verifier" tabindex="-1">Generating a verifier <a class="header-anchor" href="#generating-a-verifier" aria-label="Permalink to &quot;Generating a verifier&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scram-verifier</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;hunter2&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → {SCRAM-SHA-256}600000,…</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scram-verifier</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mech</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sha1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;hunter2&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → {SCRAM-SHA-1}600000,…</span></span></code></pre></div><p><code>--mech</code> defaults to <code>sha256</code>. Use <code>sha1</code> only when a target client cannot speak SHA-256.</p><p><code>--iterations N</code> overrides the default 600 000 (2023 OWASP recommendation for SHA-256-based PBKDF2; the same default applies to SHA-1 because the iteration count is what carries the compute-cost - the digest choice is fixed by the mech). Anything below 4096 is clamped up so a typo cannot land a weak verifier in the database.</p><p>Omit <code>--password</code> to read it from stdin (one line).</p><p>The output is the literal value to drop into the SQL <code>password</code> column. Existing PLAIN-or-BCRYPT users keep working with PLAIN and LOGIN unchanged. SCRAM is still offered to them - advertisement is not per user - and a SCRAM attempt by such a user fails like a wrong password, so a client that picks SCRAM on its own needs the verifier first.</p><h2 id="mechanism-advertisement" tabindex="-1">Mechanism advertisement <a class="header-anchor" href="#mechanism-advertisement" aria-label="Permalink to &quot;Mechanism advertisement&quot;">​</a></h2><p><code>yarilo-auth</code> announces a SCRAM family when a passdb in its chain can serve verifiers of that family at all; whether a given user has one is read during the exchange, not at the handshake. The <code>sql</code>, <code>passwd-file</code> and <code>static</code> drivers all serve both families, so a chain with any of them announces all four mechanisms - whatever verifiers are actually stored. The login proxies offer what the service announced:</p><ul><li><strong>IMAP</strong> - matching mechs appear in the <code>CAPABILITY</code> reply.</li><li><strong>POP3</strong> - <code>CAPA</code> lists them after <code>SASL</code>.</li><li><strong>Submission (SMTP)</strong> - EHLO&#39;s <code>AUTH</code> extension lists them alongside <code>PLAIN LOGIN</code>.</li></ul><p>The <code>-PLUS</code> variants are additionally gated on the TLS state having the RFC 9266 exporter available (TLS 1.3+ over a real <code>*tls.<wbr>Conn</code>). Plain TCP or TLS 1.2 sessions advertise only the non-PLUS mechs.</p><h2 id="wire-shape-rfc-5802-§5" tabindex="-1">Wire shape (RFC 5802 §5) <a class="header-anchor" href="#wire-shape-rfc-5802-§5" aria-label="Permalink to &quot;Wire shape (RFC 5802 §5)&quot;">​</a></h2><p>Three-round exchange:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client-first  → &quot;n,,n=alice,r=&lt;client-nonce&gt;&quot;</span></span>
<span class="line"><span>                (or &quot;p=tls-exporter,,&quot; for the PLUS variant)</span></span>
<span class="line"><span>server-first  ← &quot;r=&lt;combined-nonce&gt;,s=&lt;base64-salt&gt;,i=&lt;iter&gt;&quot;</span></span>
<span class="line"><span>client-final  → &quot;c=&lt;base64-cb&gt;,r=&lt;combined-nonce&gt;,p=&lt;base64-proof&gt;&quot;</span></span>
<span class="line"><span>server-final  ← &quot;v=&lt;base64-server-signature&gt;&quot;</span></span></code></pre></div><p>The server-final <code>v=</code> carries an HMAC that the client verifies to confirm the server itself knew the verifier - mutual authentication without a second round-trip.</p><h2 id="channel-binding-policy" tabindex="-1">Channel binding policy <a class="header-anchor" href="#channel-binding-policy" aria-label="Permalink to &quot;Channel binding policy&quot;">​</a></h2><p>Identical for both digest families:</p><ul><li><strong>Non-PLUS</strong> (<code>SCRAM-SHA-256</code>, <code>SCRAM-SHA-1</code>): client MUST send <code>n,,</code> or <code>y,,</code>. <code>p=…</code> is rejected because the client should have picked the PLUS mechanism if it has channel binding.</li><li><strong>PLUS</strong> (<code>SCRAM-SHA-256-PLUS</code>, <code>SCRAM-SHA-1-PLUS</code>): client MUST send <code>p=tls-exporter,,</code>. <code>n,,</code> and <code>y,,</code> are downgrade attempts and rejected.</li></ul><p>The <code>y,,</code> value lets a TLS client SIGNAL that it knows about channel binding (so a wiretap attacker can be detected by a later trace) without actually using it. We accept <code>y,,</code> - operators who require strict channel binding configure clients to use the PLUS mechanism.</p><h2 id="defence-against-user-enumeration" tabindex="-1">Defence against user enumeration <a class="header-anchor" href="#defence-against-user-enumeration" aria-label="Permalink to &quot;Defence against user enumeration&quot;">​</a></h2><p>When <code>LookupSCRAMSha256</code> returns <code>(nil, nil)</code> (unknown user), the SCRAM server <strong>does not short-circuit</strong>. It generates fake iter+salt+zero StoredKey and drives the full exchange through <code>client-final</code>; the proof check then fails uniformly because no client can derive a proof against a zero StoredKey.</p><p>The result: an attacker cannot tell apart &quot;user does not exist&quot; from &quot;user exists, wrong password&quot; by timing alone.</p><h2 id="iteration-count-guidance" tabindex="-1">Iteration count guidance <a class="header-anchor" href="#iteration-count-guidance" aria-label="Permalink to &quot;Iteration count guidance&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Year</th><th style="text-align:left;">Recommended minimum (SHA-256)</th></tr></thead><tbody><tr><td style="text-align:left;">2017 (RFC 7677)</td><td style="text-align:left;">4 096</td></tr><tr><td style="text-align:left;">2023 (OWASP)</td><td style="text-align:left;"><strong>600 000</strong> ← Yarilo default</td></tr></tbody></table><p>Tooling clamps anything below 4 096 up to 4 096 so a misconfig never lands trivially-cracked verifiers in the database. Operators on hardware that struggles with 600 000 can run <code>yarctl auth scram-verifier --iterations N</code> to pick a lower value (down to the 4 096 floor) - but this is a deliberate security trade-off and should be documented in the deployment&#39;s runbook.</p><h2 id="smoke-test-recipes" tabindex="-1">Smoke-test recipes <a class="header-anchor" href="#smoke-test-recipes" aria-label="Permalink to &quot;Smoke-test recipes&quot;">​</a></h2><h3 id="openssl-s-client-raw-sasl-imap" tabindex="-1"><code>openssl s_<wbr>client</code> + raw SASL (IMAP) <a class="header-anchor" href="#openssl-s-client-raw-sasl-imap" aria-label="Permalink to &quot;\`openssl s_client\` + raw SASL (IMAP)&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -quiet</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail.yarilo.example:993</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tls1_3</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">a1 CAPABILITY</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Confirm CAPABILITY lists AUTH=SCRAM-SHA-256 and (over TLS 1.3) AUTH=SCRAM-SHA-256-PLUS</span></span></code></pre></div><p>For the full multi-round exchange use a SCRAM-capable client (e.g. Thunderbird, or the Go <code>pkg.<wbr>go.<wbr>dev/<wbr>github.<wbr>com/<wbr>xdg-go/<wbr>scram</code> library) - driving SCRAM by hand against openssl is tedious because every round needs separate base64 work.</p><h3 id="thunderbird" tabindex="-1">Thunderbird <a class="header-anchor" href="#thunderbird" aria-label="Permalink to &quot;Thunderbird&quot;">​</a></h3><p>Settings → Account → Authentication method → <strong>Encrypted password (Normal password)</strong>. Thunderbird auto-selects SCRAM-SHA-256 when both the server and the configured profile advertise it. For SCRAM-SHA-256-PLUS, ensure the connection is TLS 1.3 (Tools → Options → Privacy &amp; Security → Certificates) and the server exposes the <code>+PLUS</code> capability.</p><h2 id="tuning-notes" tabindex="-1">Tuning notes <a class="header-anchor" href="#tuning-notes" aria-label="Permalink to &quot;Tuning notes&quot;">​</a></h2><ul><li>For a SCRAM exchange the verifier derivation ran once, at registration; the per-login cost is only HMAC + SHA-256 + memcmp.</li><li>A <strong>PLAIN or LOGIN</strong> login against the same verifier is different: the server re-derives it from the password, which is the full PBKDF2 - 600 000 rounds by default - on every such login. Raising the iteration count raises that cost too.</li><li>SCRAM does not benefit from the <code>auth.<wbr>cache</code> (the SCRAM exchange itself replaces what the cache would shortcut). PLAIN/LOGIN does: with the cache on, a repeated login skips the PBKDF2. Keep it configured where clients log in with PLAIN against SCRAM verifiers.</li><li>For multi-tenant deployments, rotate verifiers per-tenant by re-running <code>scram-verifier</code> and pushing fresh blobs through the SQL passdb&#39;s update path. There is no cluster-wide verifier rotation primitive - verifiers are per-user.</li></ul>`,54)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
